-- Isolated rider D1; never apply to merchant storage.
CREATE TABLE rider_runtime(id INTEGER PRIMARY KEY CHECK(id=1),environment TEXT NOT NULL CHECK(environment IN ('staging','production')),intake_enabled INTEGER NOT NULL DEFAULT 0 CHECK(intake_enabled IN (0,1)),activation_enabled INTEGER NOT NULL DEFAULT 0 CHECK(activation_enabled IN (0,1)),privacy_version TEXT,authorization_ref TEXT,CHECK(intake_enabled=0 OR (environment='production' AND privacy_version IS NOT NULL AND authorization_ref IS NOT NULL)),CHECK(activation_enabled=0 OR (environment='production' AND authorization_ref IS NOT NULL)));
INSERT INTO rider_runtime(id,environment) VALUES(1,'staging');
CREATE TABLE rider_requests(id TEXT PRIMARY KEY,request_key TEXT NOT NULL UNIQUE,payload_hash TEXT NOT NULL,identity_hash TEXT NOT NULL UNIQUE,full_name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT NOT NULL,ubigeo TEXT NOT NULL CHECK(length(ubigeo)=6),department TEXT NOT NULL,province TEXT NOT NULL,district TEXT NOT NULL,vehicle TEXT NOT NULL CHECK(vehicle IN ('bicycle','motorcycle','car')),privacy_version TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE rider_drafts(key_hash TEXT PRIMARY KEY,actor_hash TEXT NOT NULL,request_key TEXT NOT NULL UNIQUE,payload_json TEXT,expires_at INTEGER NOT NULL,receipt_id TEXT REFERENCES rider_requests(id),CHECK((payload_json IS NULL)=(receipt_id IS NOT NULL)));
CREATE INDEX rider_draft_expiry ON rider_drafts(expires_at);
CREATE TABLE rider_reviews(request_id TEXT PRIMARY KEY REFERENCES rider_requests(id) ON DELETE RESTRICT,stage TEXT NOT NULL DEFAULT 'SUBMITTED' CHECK(stage IN ('SUBMITTED','IDENTITY_VERIFIED','CONTRACT_VERIFIED','TRAINING_PASSED','ELIGIBLE','REJECTED')),version INTEGER NOT NULL DEFAULT 0,actor_id TEXT,evidence_ref TEXT,updated_at INTEGER NOT NULL);
CREATE TABLE rider_review_events(request_id TEXT NOT NULL REFERENCES rider_requests(id) ON DELETE RESTRICT,version INTEGER NOT NULL,from_stage TEXT NOT NULL,to_stage TEXT NOT NULL,actor_id TEXT NOT NULL,evidence_ref TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(request_id,version));
CREATE TRIGGER rider_request_created AFTER INSERT ON rider_requests BEGIN
 INSERT INTO rider_reviews(request_id,updated_at) VALUES(NEW.id,NEW.created_at);
 UPDATE rider_drafts SET payload_json=NULL,receipt_id=NEW.id WHERE request_key=NEW.request_key;
END;
-- No approval from initial submission; later evidence-specific guards required before real onboarding.
CREATE TRIGGER rider_review_transition BEFORE UPDATE ON rider_reviews WHEN NEW.request_id<>OLD.request_id OR NEW.version<>OLD.version+1 OR NEW.actor_id IS NULL OR NEW.evidence_ref IS NULL OR NOT ((OLD.stage='SUBMITTED' AND NEW.stage IN ('IDENTITY_VERIFIED','REJECTED')) OR (OLD.stage='IDENTITY_VERIFIED' AND NEW.stage IN ('CONTRACT_VERIFIED','REJECTED')) OR (OLD.stage='CONTRACT_VERIFIED' AND NEW.stage IN ('TRAINING_PASSED','REJECTED')) OR (OLD.stage='TRAINING_PASSED' AND NEW.stage IN ('ELIGIBLE','REJECTED'))) BEGIN SELECT RAISE(ABORT,'RIDER_TRANSITION_DENIED'); END;
CREATE TRIGGER rider_review_audit AFTER UPDATE ON rider_reviews BEGIN INSERT INTO rider_review_events VALUES(NEW.request_id,NEW.version,OLD.stage,NEW.stage,NEW.actor_id,NEW.evidence_ref,NEW.updated_at); END;
